package top.monitorglobal.tv;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.Build;
import com.google.firebase.FirebaseApp;
import com.google.firebase.FirebaseOptions;
import com.google.firebase.messaging.FirebaseMessaging;
import top.monitorglobal.mobile.BuildConfig;
/** Opt-in only. No polling service, location or overlay permission. */
final class PhonePush {
 static final String TOPIC="monitor_global_alerts_v1",EXTRA="monitor_push_alert";
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("phone-push",Context.MODE_PRIVATE);}
 static boolean configured(){return !BuildConfig.PUSH_APP_ID.isEmpty()&&!BuildConfig.PUSH_API_KEY.isEmpty()&&!BuildConfig.PUSH_PROJECT_ID.isEmpty();}
 static boolean enabled(Context c){return prefs(c).getBoolean("enabled",false);}
 static boolean allowed(Context c){return (Build.VERSION.SDK_INT<33||c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==PackageManager.PERMISSION_GRANTED)&&c.getSystemService(NotificationManager.class).areNotificationsEnabled();}
 static void channels(Context c){NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("seismic","Sismos",NotificationManager.IMPORTANCE_HIGH));n.createNotificationChannel(new NotificationChannel("tsunami","Avisos de tsunami",NotificationManager.IMPORTANCE_HIGH));NotificationChannel quiet=new NotificationChannel("information","Boletins informativos",NotificationManager.IMPORTANCE_LOW);n.createNotificationChannel(quiet);}
 static void initialize(Context c){if(!enabled(c))return;if(!configured()){PhoneBackgroundAlerts.schedule(c);return;}PhoneBackgroundAlerts.cancel(c);try{if(FirebaseApp.getApps(c).isEmpty())FirebaseApp.initializeApp(c,new FirebaseOptions.Builder().setApplicationId(BuildConfig.PUSH_APP_ID).setApiKey(BuildConfig.PUSH_API_KEY).setProjectId(BuildConfig.PUSH_PROJECT_ID).setGcmSenderId(BuildConfig.PUSH_SENDER_ID).build());FirebaseMessaging.getInstance().setAutoInitEnabled(true);}catch(RuntimeException e){prefs(c).edit().putString("status","Falha ao iniciar notificações. Tente ativar novamente.").apply();}}
 static void enable(Activity c,Runnable done){if(!allowed(c)){done.run();return;}prefs(c).edit().putBoolean("enabled",true).putString("status","Ativando notificações…").apply();if(!configured()){PhoneBackgroundAlerts.schedule(c);prefs(c).edit().putString("status","Avisos por verificação periódica (aprox. 30 min; o Android pode atrasar). Não é push instantâneo.").apply();done.run();return;}PhoneBackgroundAlerts.cancel(c);initialize(c);try{Context app=c.getApplicationContext();com.google.android.gms.tasks.Task<Void> task=FirebaseMessaging.getInstance().subscribeToTopic(TOPIC);task.addOnCompleteListener(result->prefs(app).edit().putString("status",result.isSuccessful()?"Inscrição push confirmada. A entrega depende da conexão e do Android.":"Inscrição pendente. Toque em ativar para tentar novamente.").apply());task.addOnCompleteListener(c,result->done.run());}catch(RuntimeException e){prefs(c).edit().putString("status","Falha na inscrição. Tente novamente.").apply();done.run();}}
 static boolean testLocal(Context c){if(!allowed(c))return false;long now=System.currentTimeMillis();Alert a=new Alert("local-notification-test","earthquake",Long.toString(now),"TESTE LOCAL · Não é alerta real","Verifica somente a notificação deste aparelho; não confirma entrega pelo Firebase.","earthquake",now,now,true);a.source="Teste neste aparelho";try{return PhoneMessagingService.post(c,a,AlertCodec.write(a).toString());}catch(org.json.JSONException e){return false;}}
 static void copyTestToken(Activity c){if(!enabled(c)||!configured()||!allowed(c)){android.widget.Toast.makeText(c,"Ative as notificações primeiro.",android.widget.Toast.LENGTH_LONG).show();return;}try{FirebaseMessaging.getInstance().getToken().addOnSuccessListener(c,token->{c.getSystemService(android.content.ClipboardManager.class).setPrimaryClip(android.content.ClipData.newPlainText("Código de teste Firebase",token));android.widget.Toast.makeText(c,"Código copiado. Use somente no teste direcionado do Firebase; não publique esse código.",android.widget.Toast.LENGTH_LONG).show();}).addOnFailureListener(c,error->android.widget.Toast.makeText(c,"Não foi possível obter o código agora. Tente novamente com conexão.",android.widget.Toast.LENGTH_LONG).show());}catch(RuntimeException e){android.widget.Toast.makeText(c,"Ative as notificações e tente novamente.",android.widget.Toast.LENGTH_LONG).show();}}
 static void disable(Context c){prefs(c).edit().putBoolean("enabled",false).putString("status","Notificações desativadas neste aplicativo.").apply();PhoneBackgroundAlerts.cancel(c);try{FirebaseMessaging.getInstance().unsubscribeFromTopic(TOPIC);FirebaseMessaging.getInstance().setAutoInitEnabled(false);}catch(RuntimeException ignored){}}
 static String status(Context c){if(!enabled(c))return "Notificações desativadas. Os dados são atualizados enquanto o aplicativo está aberto. Ative para receber avisos fora do aplicativo.";if(!allowed(c))return "O Android bloqueou as notificações. Confira as configurações do aplicativo.";if(!configured())return "Avisos de sismos e tsunami por verificação periódica (aprox. 30 min), sem Firebase. Podem atrasar ou não chegar quando o sistema restringe atividades em segundo plano.";return prefs(c).getString("status","Confirmando inscrição push…");}
}
